SELECT P.ID, P.TIPO, P.JEITO, P.SERVE, P.QUANDO, P.TITULO, P.INSTRUCAO, P.SEGUNDO, V.ID VIDEO_ID, V.YT_VIDEO_ID, V.TITULO VIDEO, C.NOME CANAL, (SELECT COUNT(*) FROM PRATICA_DIARIO D WHERE D.PRATICA_ID = P.ID) VEZES, (SELECT MAX(D.DIA) FROM PRATICA_DIARIO D WHERE D.PRATICA_ID = P.ID) ULTIMA FROM PRATICAS P JOIN VIDEOS V ON V.ID = P.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.STATUS = 'ESTUDADO' AND P.CONSELHO = 0 AND CHAR_LENGTH(P.INSTRUCAO) > 40 AND ('{{fin}}' = '' OR FIND_IN_SET('{{fin}}', P.SERVE) OR CONCAT(',', P.SERVE) LIKE CONCAT('%,', '{{fin}}', '.%')) ORDER BY CRC32(CONCAT(P.ID, '-', '{{dia}}', '-', {{vez}})) LIMIT 1